  ["Miss Celeste?"] = "Senhorita Celeste?",
  ["Miss Celeste? Why are you... Oh no! No wonder I felt like I had forgotten something..."] = "Senhorita Celeste? Por que você está... Ah, não! Não admira que eu senti como se tivesse esquecido alguma coisa...",
  ["Celeste is\r\nan incompetent daughter"] = "Celeste é\r\numa filha incompetente",
  ["Celeste is\r\na coward who fears spring"] = "Celeste é\r\numa covarde que teme a primavera",
  ["Celeste is\r\na faithless lover"] = "Celeste é\r\numa amante infiel",
  ["Celeste is\r\nan obscure dreamer"] = "Celeste é\r\numa sonhadora obscura",
  ["Celeste's letter"] = "A carta de Celeste",
  ["Sally wants to play the piano for me"] = "Sally quer tocar piano para mim",
  ["Sally's favorite tune, which she played while helping couples resolve marriage proposal crises at the Cafe\n."] = "A música favorita de Sally, que ela tocou enquanto ajudava casais a resolver crises de pedidos de casamento no Café\n.",
  ["After Sally fell ill, I often regretted not studying medicine sooner."] = "Depois que Sally adoeceu, muitas vezes me arrependi de não ter estudado medicina antes.",
  ["Sally Moves to the Piano"] = "Sally muda para o piano",
  ["Sally! Oh no!"] = "Sally! Oh não!",
  ["Sally! You have a package!"] = "Sally! Você tem um pacote!",
  ["Canned Berries"] = "Frutas Enlatadas",
  ["Mosh "] = "Mosh",
  ["Didn't Mr. Morian come here after reading that article too?"] = "O Sr. Morian não veio aqui depois de ler aquele artigo também?",
  ["Mr. Morian, your vest buttons were buttoned yesterday, why are they undone today?"] = "Sr. Morian, os botões do seu colete foram abotoados ontem, por que estão desabotoados hoje?",
  ["Monica"] = "Mônica",
  ["Monica "] = "Mônica",
  ["Monica will definitely be surprised by this gift!"] = "Com certeza Mônica vai se surpreender com esse presente!",
